// Build dashboard stats
const videos = $('Read Videos').all().map(i => i.json).filter(v => v && v.run_id);
const logs = $('Read Logs').all().map(i => i.json).filter(l => l && l.timestamp);
const now = new Date();
const day24h = new Date(now.getTime() - 24*3600*1000);
const day7d = new Date(now.getTime() - 7*24*3600*1000);

const published = videos.filter(v => v.final_status === 'published');
const failed = videos.filter(v => v.final_status === 'partial_failure' || v.final_status === 'failed');
const last24 = videos.filter(v => new Date(v.completed_at) > day24h);
const last7 = videos.filter(v => new Date(v.completed_at) > day7d);

const errors = logs.filter(l => l.level === 'ERROR');
const errors24 = errors.filter(l => new Date(l.timestamp) > day24h);

// Upcoming = videos completed in last 30 min that may still be in scheduled state
const upcoming = videos.slice(-10).filter(v => v.yt_status === 'scheduled' || v.fb_status === 'scheduled');

const stats = {
  generated_total: videos.length,
  published_total: published.length,
  failed_total: failed.length,
  generated_last_24h: last24.length,
  generated_last_7d: last7.length,
  errors_total: errors.length,
  errors_last_24h: errors24.length,
  upcoming_scheduled: upcoming.length,
  last_run: videos[videos.length - 1] || null,
  recent_videos: videos.slice(-15).reverse().map(v => ({
    run_id: v.run_id,
    completed_at: v.completed_at,
    title: v.idea_title,
    yt_url: v.youtube_url,
    fb_url: v.facebook_url,
    drive_url: v.drive_url,
    status: v.final_status
  })),
  recent_errors: errors.slice(-10).reverse().map(e => ({
    timestamp: e.timestamp,
    run_id: e.run_id,
    stage: e.stage,
    message: e.message
  })),
  total_views: 0,
  generated_at: now.toISOString()
};
return [{ json: stats }];

// Render HTML dashboard
const s = $input.first().json;
const tableRows = s.recent_videos.map(v => `
  <tr>
    <td>${v.completed_at || ''}</td>
    <td>${v.title || ''}</td>
    <td><span class="pill ${v.status}">${v.status || ''}</span></td>
    <td>${v.yt_url ? `<a href='${v.yt_url}' target='_blank'>YT</a>` : '-'}</td>
    <td>${v.fb_url ? `<a href='${v.fb_url}' target='_blank'>FB</a>` : '-'}</td>
    <td>${v.drive_url ? `<a href='${v.drive_url}' target='_blank'>Drive</a>` : '-'}</td>
  </tr>
`).join('');
const errorRows = s.recent_errors.map(e => `
  <tr>
    <td>${e.timestamp}</td>
    <td>${e.run_id}</td>
    <td>${e.stage}</td>
    <td>${(e.message || '').slice(0, 150)}</td>
  </tr>
`).join('');
const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<title>AI Video Channel Dashboard</title>
<meta http-equiv="refresh" content="60"/>
<style>
  body { font-family: -apple-system, system-ui, Segoe UI, Roboto, sans-serif; background: #0e1116; color: #e6edf3; margin: 0; padding: 24px; }
  h1 { margin: 0 0 8px; font-weight: 600; }
  .sub { color:#8b949e; margin-bottom: 24px; font-size: 13px; }
  .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 16px; margin-bottom: 28px; }
  .card { background:#161b22; border:1px solid #30363d; border-radius:10px; padding:16px; }
  .card .label { color:#8b949e; font-size:12px; text-transform:uppercase; letter-spacing:.5px; }
  .card .value { font-size:30px; font-weight:600; margin-top:6px; }
  table { width:100%; border-collapse:collapse; background:#161b22; border:1px solid #30363d; border-radius:10px; overflow:hidden; }
  th, td { padding:10px 12px; text-align:left; border-bottom:1px solid #21262d; font-size:13px; }
  th { background:#0d1117; color:#8b949e; font-weight:500; text-transform:uppercase; font-size:11px; }
  a { color:#58a6ff; text-decoration:none; }
  .pill { padding:2px 8px; border-radius:12px; font-size:11px; font-weight:500; }
  .pill.published { background:#1f6f3a; color:#aff5c4; }
  .pill.partial_failure { background:#7a3a1c; color:#ffd6b3; }
  .pill.failed { background:#7d1f23; color:#ffb3b8; }
  h2 { margin-top: 32px; font-size:18px; }
</style>
</head>
<body>
  <h1>AI Video Channel</h1>
  <div class="sub">Auto-refreshing dashboard - last updated ${s.generated_at}</div>
  <div class="grid">
    <div class="card"><div class="label">Videos Generated</div><div class="value">${s.generated_total}</div></div>
    <div class="card"><div class="label">Published</div><div class="value">${s.published_total}</div></div>
    <div class="card"><div class="label">Failed</div><div class="value">${s.failed_total}</div></div>
    <div class="card"><div class="label">Last 24h</div><div class="value">${s.generated_last_24h}</div></div>
    <div class="card"><div class="label">Last 7 days</div><div class="value">${s.generated_last_7d}</div></div>
    <div class="card"><div class="label">Upcoming Scheduled</div><div class="value">${s.upcoming_scheduled}</div></div>
    <div class="card"><div class="label">Errors (24h)</div><div class="value">${s.errors_last_24h}</div></div>
    <div class="card"><div class="label">Total Views</div><div class="value">${s.total_views}*</div></div>
  </div>
  <h2>Recent Videos</h2>
  <table>
    <thead><tr><th>Completed</th><th>Title</th><th>Status</th><th>YT</th><th>FB</th><th>Drive</th></tr></thead>
    <tbody>${tableRows}</tbody>
  </table>
  <h2>Recent Errors</h2>
  <table>
    <thead><tr><th>Time</th><th>Run</th><th>Stage</th><th>Message</th></tr></thead>
    <tbody>${errorRows}</tbody>
  </table>
  <p style="color:#8b949e;font-size:12px;margin-top:24px">* Total views requires YouTube + Facebook analytics integration (see future-integration TODO).</p>
</body>
</html>`;
return [{ json: { html } }];
